#!/usr/bin/env python3
"""Run real applications behind Vapache with reproducible stochastic sampling."""

from __future__ import annotations

import sys

# Deployment runs must not write generated bytecode back into the checkout.
sys.dont_write_bytecode = True

import argparse
import collections
import contextlib
import hashlib
import importlib.util
import itertools
import json
import os
import random
import secrets
import shutil
import subprocess
import time
import tomllib
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from lib import CaseContext, DeploymentError, ROOT, privilege_prefix


HERE = Path(__file__).resolve().parent
SCENARIOS = HERE / "scenarios"


@dataclass(frozen=True)
class Scenario:
    identifier: str
    title: str
    path: Path
    nightly: bool
    timeout_seconds: int
    disk_mb: int
    modes: tuple[str, ...]
    upstreams: tuple[str, ...]
    images: tuple[str, ...]
    prerequisites: tuple[str, ...]
    dimensions: dict[str, tuple[str, ...]]
    canonical: dict[str, str]

    def variants(self) -> list[dict[str, str]]:
        names = sorted(self.dimensions)
        return [
            dict(zip(names, values, strict=True))
            for values in itertools.product(*(self.dimensions[name] for name in names))
        ]


@dataclass(frozen=True)
class Case:
    scenario: Scenario
    variant: dict[str, str]

    @property
    def identifier(self) -> str:
        suffix = ",".join(f"{name}={self.variant[name]}" for name in sorted(self.variant))
        digest = hashlib.sha256(suffix.encode()).hexdigest()[:10]
        return f"{self.scenario.identifier}-{digest}"

    def record(self) -> dict[str, Any]:
        return {
            "case": self.identifier,
            "scenario": self.scenario.identifier,
            "title": self.scenario.title,
            "variant": self.variant,
            "modes": self.scenario.modes,
            "upstreams": self.scenario.upstreams,
            "images": self.scenario.images,
            "disk_mb": self.scenario.disk_mb,
        }


def load_scenarios() -> list[Scenario]:
    scenarios: list[Scenario] = []
    for manifest in sorted(SCENARIOS.glob("*/scenario.toml")):
        data = tomllib.loads(manifest.read_text())
        dimensions = {name: tuple(values) for name, values in data["dimensions"].items()}
        canonical = dict(data["canonical"])
        scenario = Scenario(
            identifier=data["id"],
            title=data["title"],
            path=manifest.parent,
            nightly=bool(data.get("nightly", False)),
            timeout_seconds=int(data.get("timeout_seconds", 300)),
            disk_mb=int(data.get("disk_mb", 512)),
            modes=tuple(data.get("modes", [])),
            upstreams=tuple(data.get("upstreams", [])),
            images=tuple(data.get("images", [])),
            prerequisites=tuple(data.get("prerequisites", [])),
            dimensions=dimensions,
            canonical=canonical,
        )
        if set(canonical) != set(dimensions):
            raise DeploymentError(f"{manifest}: canonical dimensions do not match dimensions table")
        for name, value in canonical.items():
            if value not in dimensions[name]:
                raise DeploymentError(f"{manifest}: canonical {name}={value!r} is not selectable")
        for image in scenario.images:
            if "@sha256:" not in image:
                raise DeploymentError(f"{manifest}: image is not pinned by digest: {image}")
        if not (scenario.path / "driver.py").exists():
            raise DeploymentError(f"{manifest}: missing driver.py")
        scenarios.append(scenario)
    if not scenarios:
        raise DeploymentError(f"no deployment scenarios found under {SCENARIOS}")
    return scenarios


def cases_for_scenario(scenario: Scenario) -> list[Case]:
    return [Case(scenario, variant) for variant in scenario.variants()]


def choose_cases(
    scenarios: list[Scenario],
    *,
    profile: str,
    rng: random.Random,
    sample_count: int,
    only: str | None,
) -> list[Case]:
    if only:
        scenarios = [scenario for scenario in scenarios if scenario.identifier == only]
        if not scenarios:
            raise DeploymentError(f"unknown scenario {only!r}")
    if profile == "nightly":
        return [Case(scenario, scenario.canonical) for scenario in scenarios if scenario.nightly]
    all_cases = [case for scenario in scenarios for case in cases_for_scenario(scenario)]
    if profile == "full":
        return all_cases
    if sample_count < 1:
        raise DeploymentError("sample count must be positive")
    target = min(sample_count, len(all_cases))
    selected: list[Case] = []
    # Stratification keeps application coverage while dimensions remain stochastic.
    shuffled_scenarios = list(scenarios)
    rng.shuffle(shuffled_scenarios)
    for scenario in shuffled_scenarios[:target]:
        selected.append(rng.choice(cases_for_scenario(scenario)))
    remaining = [case for case in all_cases if case not in selected]
    rng.shuffle(remaining)
    selected.extend(remaining[: target - len(selected)])
    rng.shuffle(selected)
    return selected


def group_cases_by_scenario(cases: list[Case]) -> list[Case]:
    """Avoid re-pulling an image for every sampled variant of one application."""
    order = list(dict.fromkeys(case.scenario.identifier for case in cases))
    return [case for identifier in order for case in cases if case.scenario.identifier == identifier]


def import_driver(scenario: Scenario):
    path = scenario.path / "driver.py"
    module_name = "vapache_deployment_" + scenario.identifier.replace("-", "_")
    spec = importlib.util.spec_from_file_location(module_name, path)
    if spec is None or spec.loader is None:
        raise DeploymentError(f"cannot load {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if not hasattr(module, "run"):
        raise DeploymentError(f"{path}: driver must export run(context, variant)")
    return module


def require_prerequisites(scenario: Scenario) -> None:
    missing = [name for name in scenario.prerequisites if shutil.which(name) is None]
    if missing:
        raise DeploymentError(
            f"{scenario.identifier}: missing prerequisite(s): {', '.join(sorted(missing))}"
        )


def check_disk(scenario: Scenario) -> None:
    default_reserve = "2048" if scenario.images else "256"
    reserve_mb = int(os.environ.get("VAPACHE_DEPLOY_DISK_RESERVE_MB", default_reserve))
    docker_root = Path("/")
    if scenario.images and shutil.which("docker"):
        result = subprocess.run(
            ["docker", "info", "--format", "{{.DockerRootDir}}"],
            text=True,
            capture_output=True,
            check=False,
        )
        candidate = Path(result.stdout.strip()) if result.returncode == 0 else Path("/")
        if candidate.exists():
            docker_root = candidate
    free_mb = shutil.disk_usage(docker_root).free // (1024 * 1024)
    required_mb = scenario.disk_mb + reserve_mb
    if free_mb < required_mb:
        raise DeploymentError(
            f"{scenario.identifier}: requires {scenario.disk_mb} MiB plus a {reserve_mb} MiB "
            f"Docker safety reserve, only {free_mb} MiB is available on {docker_root}"
        )


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--profile", choices=("nightly", "sample", "full"), default="nightly")
    parser.add_argument("--scenario", help="restrict the run to one scenario")
    parser.add_argument("--sample-count", type=int, default=10)
    parser.add_argument("--seed", type=lambda value: int(value, 0))
    parser.add_argument("--vapached", type=Path, default=ROOT / "target/release/vapached")
    default_run_root = Path("/run/vapache-deployments") if os.geteuid() == 0 else Path("/tmp/vapache-deployments")
    parser.add_argument("--run-root", type=Path, default=default_run_root)
    parser.add_argument("--artifacts", type=Path, default=Path("/tmp/vapache-deployment-results"))
    parser.add_argument("--plan-only", action="store_true")
    parser.add_argument("--remove-images", action=argparse.BooleanOptionalAction, default=True)
    parser.add_argument("--benchmark", action="store_true")
    parser.add_argument(
        "--allow-same-identity",
        action="store_true",
        help="developer-only: skip the distinct host service-identity prerequisite",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    seed = args.seed if args.seed is not None else secrets.randbits(64)
    rng = random.Random(seed)
    scenarios = load_scenarios()
    cases = choose_cases(
        scenarios,
        profile=args.profile,
        rng=rng,
        sample_count=args.sample_count,
        only=args.scenario,
    )
    cases = group_cases_by_scenario(cases)
    run_id = f"{int(time.time())}-{seed:016x}"
    artifact_root = args.artifacts.resolve() / run_id
    run_root = args.run_root.resolve() / run_id
    args.run_root.resolve().mkdir(parents=True, exist_ok=True)
    os.chmod(args.run_root.resolve(), 0o755)
    run_root.mkdir(parents=True, exist_ok=True)
    os.chmod(run_root, 0o755)
    artifact_root.mkdir(parents=True, exist_ok=True)
    plan = {
        "version": 1,
        "profile": args.profile,
        "seed": seed,
        "run_id": run_id,
        "cases": [case.record() for case in cases],
    }
    (artifact_root / "plan.json").write_text(json.dumps(plan, indent=2, sort_keys=True) + "\n")
    print(json.dumps(plan, indent=2, sort_keys=True), flush=True)
    if args.plan_only:
        with contextlib.suppress(OSError):
            run_root.rmdir()
        return 0
    if not args.vapached.is_file():
        raise DeploymentError(f"Vapache binary not found: {args.vapached}")
    if os.geteuid() != 0 and not privilege_prefix() and not args.allow_same_identity:
        raise DeploymentError(
            "deployment scenarios require root or passwordless sudo so Vapache can use a distinct service identity"
        )
    if args.allow_same_identity and os.geteuid() != 0 and not privilege_prefix():
        print(
            "WARNING: local compatibility run uses the invoking identity for Vapache; "
            "CI must run without --allow-same-identity",
            file=sys.stderr,
            flush=True,
        )

    results: list[dict[str, Any]] = []
    failed = False
    remaining = collections.Counter(case.scenario.identifier for case in cases)
    for index, case in enumerate(cases, 1):
        started = time.monotonic()
        print(f"[{index}/{len(cases)}] {case.identifier}: {case.scenario.title}", flush=True)
        run_dir = run_root / case.identifier
        artifact_dir = artifact_root / case.identifier
        run_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(run_dir, 0o755)
        artifact_dir.mkdir(parents=True)
        context = CaseContext(
            scenario_id=case.scenario.identifier,
            case_id=case.identifier,
            run_dir=run_dir,
            artifact_dir=artifact_dir,
            vapached=args.vapached.resolve(),
            images=case.scenario.images,
            remove_images=args.remove_images and remaining[case.scenario.identifier] == 1,
            benchmark=args.benchmark,
        )
        error: str | None = None
        try:
            require_prerequisites(case.scenario)
            check_disk(case.scenario)
            import_driver(case.scenario).run(context, dict(case.variant))
        except Exception as exception:
            failed = True
            error = f"{type(exception).__name__}: {exception}"
            print(f"FAILED {case.identifier}: {error}", file=sys.stderr, flush=True)
        finally:
            try:
                context.close()
            except Exception as exception:
                failed = True
                cleanup_error = f"cleanup: {type(exception).__name__}: {exception}"
                error = f"{error}; {cleanup_error}" if error else cleanup_error
                print(f"FAILED {case.identifier}: {cleanup_error}", file=sys.stderr, flush=True)
            shutil.rmtree(run_dir, ignore_errors=True)
        results.append(
            {
                **case.record(),
                "duration_seconds": round(time.monotonic() - started, 3),
                "status": "failed" if error else "passed",
                "error": error,
            }
        )
        remaining[case.scenario.identifier] -= 1

    summary = {**plan, "results": results, "status": "failed" if failed else "passed"}
    (artifact_root / "summary.json").write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")
    with contextlib.suppress(OSError):
        run_root.rmdir()
    print(f"deployment integration: {summary['status']} (seed={seed}, artifacts={artifact_root})")
    return 1 if failed else 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except DeploymentError as error:
        print(f"deployment integration: {error}", file=sys.stderr)
        raise SystemExit(2)

